// Why Code: merges two sources (JSON + XML), keyword/venue scoring and 200-char Kakao chunking; no native node combines these.
const todayStr = new Date(Date.now() + 9 * 3600 * 1000).toISOString().slice(0, 10).replace(/-/g, '');
const month = todayStr.slice(4, 6);
const fmt = (d) => `${d.slice(4, 6)}.${d.slice(6, 8)}`;
const unesc = (s) => s.replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&amp;/g, '&').replace(/\s+/g, ' ').trim();

// 1) TourAPI festivals
const tourBody = $('Fetch Festivals (TourAPI)').first().json?.response?.body || {};
const tourRaw = tourBody.items && tourBody.items.item ? tourBody.items.item : [];
const tourKw = /어린이|초등|가족|아이|키즈|청소년|학생|체험|과학|동화|교육|캠프|놀이|공룡|곤충|동물|로봇|우주|인형|마술|박물관|도서관|독서/;
const tour = (Array.isArray(tourRaw) ? tourRaw : [tourRaw])
  .filter((i) => i.title && tourKw.test(i.title))
  .map((i) => ({ title: unesc(i.title), start: String(i.eventstartdate), end: String(i.eventenddate), region: String(i.addr1 || '').split(' ').slice(0, 2).join(' '), place: '' }));

// 2) Culture portal (XML)
const xml = String($input.first().json.data ?? $input.first().json ?? '');
const tag = (s, t) => { const m = s.match(new RegExp(`<${t}>([\\s\\S]*?)</${t}>`)); return m ? m[1] : ''; };
const cultKw = /어린이|초등|가족|키즈|아동|꼬마|동화|체험|영유아|놀이터/;
const noise = /독주회|잔혹|협연|대학로|마법사관/;
const cult = [...xml.matchAll(/<item>([\s\S]*?)<\/item>/g)].map((m) => m[1]).map((s) => ({
  title: unesc(tag(s, 'title')), start: tag(s, 'startDate'), end: tag(s, 'endDate'),
  region: `${tag(s, 'area')} ${tag(s, 'sigungu')}`.trim(), place: unesc(tag(s, 'place')), realm: tag(s, 'realmName'),
})).filter((i) => i.title && !noise.test(i.title) && (cultKw.test(i.title) || i.realm === '아동/가족'));

// 3) merge, dedupe, rank (public venues first, then soonest)
const pubKw = /국립|시립|도립|구립|군립|문화재단|문화원|문화예술회관|문화회관|예술의전당|박물관|미술관|도서관|과학관|평생학습관|시민회관|문화의전당/;
const seen = new Set();
const picked = [...tour, ...cult]
  .filter((i) => i.end >= todayStr)
  .filter((i) => { const k = i.title.replace(/\s/g, ''); if (seen.has(k)) return false; seen.add(k); return true; })
  .map((i) => ({ ...i, pub: pubKw.test(i.place + i.title) ? 0 : 1 }))
  .sort((a, b) => a.pub - b.pub || a.start.localeCompare(b.start))
  .slice(0, 10);

if (!picked.length) {
  return [{ json: { text: `[초등 행사 ${month}월] 이번 달 조건에 맞는 공공 행사가 없습니다.` } }];
}
const lines = picked.map((i, n) => {
  const t = i.title.length > 22 ? i.title.slice(0, 21) + '…' : i.title;
  const dates = i.start === i.end ? fmt(i.start) : `${fmt(i.start)}~${fmt(i.end)}`;
  return `${n + 1}. ${t} ${dates} (${i.region})`;
});
const chunks = [];
let cur = [];
for (const l of lines) {
  if ((cur.join('\n') + '\n' + l).length > 155) { chunks.push(cur); cur = []; }
  cur.push(l);
}
if (cur.length) chunks.push(cur);
return chunks.map((c, i) => ({
  json: { text: `[초등 행사 ${month}월 보고 ${picked.length}건] (${i + 1}/${chunks.length})\n${c.join('\n')}`.slice(0, 200) },
}));
